INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'TeambyDivision' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'TeambyDivision' AS SQL_NM, 'SELECT DISTINCT A.DIVISION_ID AS DIVISION_ID, C.DEPT_ID AS CODE     , CASE @langCd WHEN ''EN'' THEN C.DEPT_NAME_EN           WHEN ''CN'' THEN C.DEPT_NAME_CN           ELSE C.DEPT_NAME_KO       END AS NAME FROM SCM_MST_SITE_ITEM A    , SCM_MST_SSO_DEPT_INFO C WHERE 1=1 AND   A.DEPT_ID = C.DEPT_ID AND   A.DIVISION_ID IN (SELECT DISTINCT UNIT_ID                         FROM   SCM_ADM_USER_GR_UNIT_AUTH_MPG_M A                         WHERE  USER_ID = @sesUserId                         AND    UNIT_TP_CD = ''D'') ORDER BY DIVISION_ID, NAME, CODE' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

