WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'EndCustomerByDivisionDept' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'End Customer by division, team' AS SQL_NM, 'SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID,     A.END_CUSTOMER AS CODE,     NVL(D.SEGMENT3, A.END_CUSTOMER) AS NAME FROM ( 	SELECT DISTINCT 	     site.DIVISION_ID 	   , site.END_CUSTOMER 	   , item.DEPT_ID, item.PROJECT_CODE 	   , site.SCM_SITE_ID AS CODE 	   , site.SCM_SITE_ID AS NAME 	FROM      SCM_MST_SITE site 	LEFT JOIN SCM_MST_SITE_ITEM item 	       ON site.DIVISION_ID = item.DIVISION_ID 	      AND site.SCM_SITE_ID = item.SCM_SITE_ID ) A LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D     ON A.DIVISION_ID = D.SEGMENT1    AND A.END_CUSTOMER = D.SEGMENT2    AND D.LOOKUP_TYPE = ''END_CUSTOMER''    AND D.VALID_YN = ''Y'' WHERE 1 = 1 --  AND ( --        (@divisionId = NULL OR @divisionId = ''ALL'' OR @divisionId = '''') --        OR A.DIVISION_ID IN ( --            SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND ( --        (@deptId = NULL OR @deptId = ''ALL'' OR @deptId = '''') --        OR A.DEPT_ID IN ( --            SELECT REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND A.DIVISION_ID IN ( --        SELECT DISTINCT UNIT_ID --        FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M --        WHERE USER_ID = @sesUserId --          AND UNIT_TP_CD = ''D'' --      )   AND A.DIVISION_ID IS NOT NULL   AND A.DEPT_ID IS NOT NULL   AND A.END_CUSTOMER IS NOT NULL ORDER BY A.END_CUSTOMER' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'SiteByEndCustomer' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'SCM Site by End Customer' AS SQL_NM, 'SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID, 	A.END_CUSTOMER AS END_CUSTOMER,     A.SCM_SITE_ID AS CODE,     A.SCM_SITE_ID AS NAME FROM SCM_MST_SITE A LEFT JOIN SCM_MST_SITE_ITEM B     ON (@divisionId = ''40'' AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID) LEFT JOIN (     SELECT REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) AS token     FROM DUAL     CONNECT BY REGEXP_SUBSTR(@endCustomer, ''[^,]+'', 1, LEVEL) IS NOT NULL ) C ON (1=1) WHERE A.SITE_TYPE = ''SALES''   AND A.VALID_YN = ''Y''   AND (         @divisionId IS NULL         OR @divisionId = ''''         OR @divisionId = ''ALL''         OR A.DIVISION_ID IN (             SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL)             FROM DUAL             CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL         )       )   AND (         @endCustomer IS NULL         OR @endCustomer = ''''         OR @endCustomer = ''ALL''         OR (             @divisionId <> ''40''             AND A.END_CUSTOMER = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN A.END_CUSTOMER                 ELSE C.token             END         )         OR (             @divisionId = ''40''             AND B.PROJECT_CODE = CASE                 WHEN @endCustomer = ''ALL'' OR @endCustomer = '''' THEN B.PROJECT_CODE                 ELSE C.token             END         )       )   AND A.DIVISION_ID IN (         SELECT DISTINCT UNIT_ID         FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M         WHERE USER_ID = @sesUserId           AND UNIT_TP_CD = ''D''     ) ORDER BY A.SCM_SITE_ID ASC' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'MenuType' AS SQL_ID, 'ALL' AS MDU_DIVS_CD, 'Menu Type' AS SQL_NM, '   SELECT  T1.SEGMENT1 CODE, NVL(MSG.MSG_NM, T1.DESCRIPTION) NAME      FROM  SCM_ADM_LOOKUP_MASTER_DETAIL T1 LEFT JOIN  SCM_ADM_MSG_M MSG        ON  T1.SEGMENT2 = MSG.MSG_ID       AND  MSG.LANG_CD = @sesLangCd     WHERE  1=1       AND  T1.LOOKUP_TYPE = ''MNU_TP_CD''       AND  T1.VALID_YN = ''Y''  ORDER BY  T1.LOOKUP_TYPE, T1.DISPLAY_SEQ' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
