INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'SalesCompany' AS SQL_ID, 'ALL' AS MDU_DIVS_CD, 'Sales Company 조회' AS SQL_NM, 'SELECT DISTINCT 	   s.DIVISION_ID AS DIVISION_ID 	 , S.COMPANY_ID AS CODE 	 , S.COMPANY_ID AS NAME FROM   SCM_MST_SITE S WHERE 1=1   AND SITE_TYPE = ''PLANT''   AND (@plantId IS NULL OR @plantId='''' OR PLANT_ID=@plantId)   AND (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId) UNION ALL SELECT DISTINCT 	   S.DIVISION_ID AS DIVISION_ID 	 , COMPANY_ID AS CODE 	 , COMPANY_ID AS NAME FROM   SCM_MST_SITE S WHERE  1 = 1   AND  SITE_TYPE = ''CORP''   AND  (@plantId IS NULL OR @plantId='''' OR PLANT_ID=@plantId)   AND  (@divisionId IS NULL OR @divisionId='''' OR S.DIVISION_ID=@divisionId) ORDER BY 1,2   --조건과 함께 조회시 --SELECT DISTINCT --	   S.COMPANY_ID AS CODE --	 , S.COMPANY_ID AS NAME --FROM   SCM_MST_SITE S WITH(NOLOCK) --INNER join (SELECT DISTINCT I.DIVISION_ID, I.COMPANY_ID, I.SCP_OPERATION_GROUP --[C20200608-000328] SalesCompany 콤보는 Item Master의 Company ID, Operation Group 기준으로 조회 --			from   scm_mst_project_item SI with(nolock) --			inner join SCM_MST_ITEM_SN I with(nolock) --			on     SI.ITEM_ID = I.ITEM_ID --			--AND    SCP_OPERATION_GROUP IS NOT NULL --[C20200608-000328] SalesCompany 콤보는 Item Master의 Company ID, Operation Group 기준으로 조회 --			WHERE  1=1 --si.valid_yn = ''Y'' --[C20200818-000264] Project_Item Master Valid 조건 제외, Item Master Valid 조건 추가 --			AND    i.active_flag = ''Y'' --			AND    (i.division_id LIKE ''81%'' OR i.division_id = ''82'') --			AND    i.item_type is not null --[C20200626-000172] SalesCompany, SalesPlant Item Type is not null 조건 추가 --			AND    (@Param2 IS NULL OR @Param2='''' OR SI.DIVISION_ID=@Param2) --			AND    (@Param3 IS NULL OR @Param3='''' OR SI.PROJECT_CODE=@Param3) --			AND    (@Param4 IS NULL OR @Param4='''' OR SI.ITEM_ID=@Param4) -- --			UNION ALL --			SELECT DISTINCT I.DIVISION_ID, I.COMPANY_ID, I.SCP_OPERATION_GROUP --[C20200608-000328] SalesCompany 콤보는 Item Master의 Company ID, Operation Group 기준으로 조회 --			from   SCM_MST_ITEM_SN I with(nolock) --			WHERE  1=1 --			AND    i.active_flag = ''Y'' --[C20200818-000264] Project_Item Master Valid 조건 제외, Item Master Valid 조건 추가 --			AND    i.division_id in (''40'') --			AND    i.item_type is not null --[C20200626-000172] SalesCompany, SalesPlant 에 Item Type is not null 조건 추가 --			AND    (@Param2 IS NULL OR @Param2='''' OR I.DIVISION_ID=@Param2) --			AND    (@Param4 IS NULL OR @Param4='''' OR I.ITEM_ID=@Param4) --			) SS --ON  S.DIVISION_ID = SS.DIVISION_ID --AND S.OPERATION_GROUP = ISNULL(SS.SCP_OPERATION_GROUP, S.OPERATION_GROUP) --AND S.COMPANY_ID = SS.COMPANY_ID --[C20200608-000328] SalesCompany 콤보는 Item Master의 Company ID, Operation Group 기준으로 조회 --WHERE  1 = 1 --AND    SITE_TYPE = ''PLANT'' ----AND    OSP_YN    <> ''Y'' --AND    (@Param1 IS NULL OR @Param1='''' OR PLANT_ID=@Param1) --AND    (@Param2 IS NULL OR @Param2='''' OR S.DIVISION_ID=@Param2) --UNION ALL --SELECT DISTINCT --	   COMPANY_ID AS CODE --	 , COMPANY_ID AS NAME --FROM   SCM_MST_SITE S WITH(NOLOCK) --WHERE  1 = 1 --AND    SITE_TYPE = ''CORP'' --AND    (@Param1 IS NULL OR @Param1='''' OR PLANT_ID=@Param1) --AND    (@Param2 IS NULL OR @Param2='''' OR S.DIVISION_ID=@Param2) --ORDER BY 1,2 ' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-04-22 14:47:24','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
