WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'BizType' AS SQL_ID, 'CM' AS MDU_DIVS_CD, 'Biz Type (BIZ_TYPE_NAME for combo)' AS SQL_NM, 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''DM_BIZ_TYPE''' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'admin' AS CREATED_BY, TO_DATE('2026-06-15 22:13:20','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-06-15 22:25:14','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'TeambyDivision2' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'TeambyDivision2 (전체 부서, 변수없이 DISTINCT)' AS SQL_NM, 'SELECT DISTINCT C.DEPT_ID AS CODE
       , CASE @langCd WHEN ''EN'' THEN C.DEPT_NAME_EN
                      WHEN ''CN'' THEN C.DEPT_NAME_CN
                      ELSE C.DEPT_NAME_KO END AS NAME
  FROM (
        SELECT B.DEPT_ID AS DEPT_ID
          FROM SCM_MST_SITE_ITEM A
             , SCM_MST_SSO_USER_INFO B
         WHERE A.OWNER = B.USER_ID
        UNION
        SELECT A.DEPT_ID AS DEPT_ID
          FROM SCM_MST_SITE A
         WHERE A.SITE_TYPE = ''SALES''
       ) S
  JOIN SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = S.DEPT_ID
 ORDER BY NAME' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-06-25 11:33:46','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-06-25 11:33:46','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'DMF0043_UPPER_DEPT' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'DMF0043 기여율메인 부문(상위부문) 콤보' AS SQL_NM, 'SELECT DEPT_INFO.DEPT_ID AS CODE
       , CASE @langCd WHEN ''EN'' THEN DEPT_INFO.DEPT_NAME_EN
                      WHEN ''CN'' THEN DEPT_INFO.DEPT_NAME_CN
                      ELSE DEPT_INFO.DEPT_NAME_KO END AS NAME
  FROM (
        SELECT DISTINCT C.UPPER_DEPT_ID
          FROM SCM_MST_SITE_ITEM A
             , SCM_MST_SSO_USER_INFO B
             , SCM_MST_SSO_DEPT_INFO C
         WHERE A.OWNER = B.USER_ID
           AND B.DEPT_ID = C.DEPT_ID
           AND A.DIVISION_ID = ''40''
       ) MA
  JOIN SCM_MST_SSO_DEPT_INFO DEPT_INFO ON DEPT_INFO.DEPT_ID = MA.UPPER_DEPT_ID
 ORDER BY NAME' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-06-25 11:33:46','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-06-25 11:33:46','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
