WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'sysOperationOptions' AS SQL_ID, 'SYS' AS MDU_DIVS_CD, 'DQ 비교연산자' AS SQL_NM, 'SELECT ''='' AS CODE, ''='' AS NAME FROM DUAL UNION ALL SELECT ''IN'' AS CODE, ''IN'' AS NAME FROM DUAL UNION ALL SELECT ''LIKE'' AS CODE, ''LIKE'' AS NAME FROM DUAL UNION ALL SELECT ''>'' AS CODE, ''>'' AS NAME FROM DUAL UNION ALL SELECT ''<'' AS CODE, ''<'' AS NAME FROM DUAL' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'admin' AS CREATED_BY, TO_DATE('2026-07-09 11:44:15','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-07-09 11:44:15','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE FROM (SELECT 'CELL_PROD_SITE_ID' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'DMF0021 Cell Prod Site 셀 콤보 (div40 Catch_Up)' AS SQL_NM, 'SELECT SEGMENT1 AS CODE, ATTRIBUTE1 AS NAME
FROM SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''SP_CELL_PROD_SITE'' AND SEGMENT1 = ''-'' AND VALID_YN = ''Y''
  AND NOT EXISTS (SELECT 1 FROM SCM_MST_ITEM_SN I
                   WHERE I.ACTIVE_FLAG = ''Y'' AND I.FORECAST_INFO_BIZ_TYPE = ''CELL''
                     AND I.DIVISION_ID = @divisionId AND I.ITEM_ID = @itemId
                     AND @itemId IS NOT NULL AND @itemId <> ''ALL'')
UNION ALL
SELECT DISTINCT S.SCM_SITE_ID AS CODE, M.ATTRIBUTE1 AS NAME
FROM SCM_MST_SITE S
JOIN (SELECT DISTINCT I.DIVISION_ID, I.COMPANY_ID, I.SCP_OPERATION_GROUP
        FROM SCM_MST_ITEM_SN I
       WHERE I.ACTIVE_FLAG = ''Y'' AND I.ITEM_TYPE IS NOT NULL
         AND I.FORECAST_INFO_BIZ_TYPE = ''CELL''
         AND (@divisionId IS NULL OR I.DIVISION_ID = @divisionId)
         AND (@itemId IS NULL OR @itemId = ''ALL'' OR I.ITEM_ID = @itemId)) SS
  ON S.DIVISION_ID = SS.DIVISION_ID AND S.OPERATION_GROUP = SS.SCP_OPERATION_GROUP
 AND S.COMPANY_ID = SS.COMPANY_ID
JOIN SCM_ADM_LOOKUP_MASTER_DETAIL M
  ON M.LOOKUP_TYPE = ''SP_CELL_PROD_SITE'' AND M.SEGMENT1 = S.SCM_SITE_ID AND M.VALID_YN = ''Y''
WHERE S.SITE_TYPE = ''PLANT'' AND S.OPERATION_GROUP = ''A'' AND S.OSP_YN = ''N''' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'admin' AS CREATED_BY, TO_DATE('2026-07-14 23:09:14','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-07-14 23:09:14','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M t WHERE t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD);

COMMIT;

